/** Safe OSC 8 display links. Never launch a process or trust escape sequences from a model. */
import { posix, win32 } from 'node:path'
import { safeText } from './terminal.ts'
import type { Row, Span } from './rich-text.ts'
/**
 * Only browser URLs are accepted from Markdown; local file URIs are generated by us.
 * @param value - candidate URL.
 * @returns the normalized http(s) URL, or undefined when rejected.
 */
export function safeHref(value: string): string | undefined {
  if (value.length > 4096 || /[\u0000-\u0020\u007f-\u009f]/u.test(value)) return undefined
  try { const url = new URL(value); return ['https:', 'http:'].includes(url.protocol) ? url.href : undefined }
  catch { return undefined }
}
/**
 * Resolve a visible file reference without IO; line fragments are a hint to supporting openers.
 * @param reference - path with optional `:line[:column]` suffix.
 * @param cwd - absolute directory that relative paths resolve against.
 * @returns a `file://` URL with optional `#L<line>C<column>`, or undefined when not a file reference or unsafe.
 */
export function fileHref(reference: string, cwd: string): string | undefined {
  if (cwd === '' || /[\u0000-\u001f\u007f-\u009f]/u.test(reference + cwd)) return undefined
  const match = /^(.*?)(?::(\d+))?(?::(\d+))?$/u.exec(reference)
  const path = match?.[1] ?? reference
  if (!/[\\/]/u.test(path) && !/\.[a-z\d]{1,12}$/iu.test(path)) return undefined
  let url: string
  if (/^[a-z]:[\\/]/iu.test(cwd) || /^[a-z]:[\\/]/iu.test(path)) {
    const absolute = win32.resolve(cwd, path).replace(/\\/gu, '/')
    // Never turn a model supplied UNC path into an implicitly contacted network share.
    if (!/^[a-z]:\//iu.test(absolute)) return undefined
    url = `file:///${absolute.split('/').map((part, index) => index === 0 ? part : encodeURIComponent(part)).join('/')}`
  } else {
    if (!posix.isAbsolute(cwd) || path.startsWith('//')) return undefined
    // The branch is chosen by the shape of the reference, so the URL cannot be
    // built with `pathToFileURL`: on Windows that resolves a POSIX path against
    // the current drive and returns `file:///C:/...` for a remote workspace.
    url = `file://${posix.resolve(cwd, path).split('/').map(part => encodeURIComponent(part)).join('/')}`
  }
  return url + (match?.[2] === undefined ? '' : `#L${match[2]}${match[3] === undefined ? '' : `C${match[3]}`}`)
}
/**
 * Encoding occurs only at the paint boundary, after width calculation and display sanitization.
 * @param text - visible link text.
 * @param href - http(s) or `file:///` target.
 * @returns sanitized text, wrapped in an OSC 8 hyperlink when the target is accepted.
 */
export function osc8(text: string, href: string): string {
  const allowed = safeHref(href) ?? (/^file:\/\/\/[^\u0000-\u0020\u007f-\u009f]*$/u.test(href) ? href : undefined)
  return allowed === undefined ? safeText(text) : `\u001b]8;;${allowed}\u001b\\${safeText(text)}\u001b]8;;\u001b\\`
}
/** A browser URL, a path with a separator, or a `file.ext:line[:column]` reference. */
const REFERENCE = new RegExp([
  'https?://[^\\s<>"\'`]+',
  '(?:[a-z]:[\\\\/]|\\.{0,2}/)?[\\w@.~-]+(?:[\\\\/][\\w@.~-]+)+(?::\\d+(?::\\d+)?)?',
  '\\b[\\w.-]+\\.[a-z\\d]{1,12}:\\d+(?::\\d+)?',
].join('|'), 'giu')
/**
 * Annotate only visible rows, retaining the original text and mouse action geometry.
 * @param rows - rows to annotate.
 * @param cwd - directory for file references.
 * @param enabled - false strips every existing `href`.
 * @returns rows with URL and file references split into linked spans; spans with an action or href stay unchanged.
 */
export function linkRows(rows: readonly Row[], cwd: string, enabled: boolean): Row[] {
  return rows.map(value => ({ ...value, spans: value.spans.flatMap((part) => {
    if (!enabled) { const { href: _href, ...plain } = part; return [plain] }
    if (part.href !== undefined || part.action !== undefined) return [part]
    const result: Span[] = []; let at = 0
    for (const match of part.text.matchAll(REFERENCE)) {
      const text = match[0].replace(/[),;.!?]+$/u, '')
      const href = text.startsWith('http') ? safeHref(text) : fileHref(text, cwd)
      if (href === undefined) continue
      result.push({ ...part, text: part.text.slice(at, match.index) }, { ...part, text, href })
      at = match.index + text.length
    }
    if (at === 0) return [part]
    result.push({ ...part, text: part.text.slice(at) }); return result
  }) }))
}
